import { GUID, NowConfig, createConsoleLogger, type Telemetry } from '@servicenow/sdk-build-core'
import { Orchestrator, Project } from '../../src'

import * as os from 'os'
import type { FileSystem } from '@servicenow/sdk-build-core'
import memfs from 'memfs'
import { MockConnector } from '../orchestrators/mock-connector'
import { packMetadata } from '../orchestrators/utils'

describe('moveToApp', () => {
    const logger = createConsoleLogger()

    let telemetry: Telemetry

    beforeEach(() => {
        jest.clearAllMocks()
        telemetry = {
            sendEvent: jest.fn(),
            error: jest.fn(),
            startTimerEvent: jest.fn((name: string) => ({
                end: jest.fn((endArgs?: unknown) => ({
                    name,
                    ...(endArgs as object | undefined),
                })),
            })),
        } as unknown as Telemetry
    })

    test('move file to app', async () => {
        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)
        const scopeId = GUID()
        const project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'global', scopeId }, logger),
            telemetryClient: telemetry,
        })

        const orchestrator = new Orchestrator(
            project,
            new MockConnector({
                getScopeInfo: async () => {
                    return {
                        active: true,
                        appId: scopeId,
                        sysClassName: 'sys_app',
                        scope: scopeId,
                        name: 'global',
                        shortDescription: '',
                    }
                },
                download: async () => {
                    const body = await packMetadata(['businessrule.xml', 'acl.xml', 'dictionary.xml'], __dirname)
                    return new Response(body)
                },
                moveToApp: async () => {
                    return [
                        {
                            table: 'sys_dictionary',
                            sysId: '34e04723799432108aa8fcb57505d952',
                        },
                        {
                            table: 'sys_script',
                            sysId: 'cb243962f1571100a92eb60da2bce522',
                        },
                        {
                            table: 'sys_security_acl',
                            sysId: '7d45011873670010e2fda4038bf6a79e',
                        },
                    ]
                },
            })
        )
        expect(project.getFiles()).toHaveLength(3)

        const result = await orchestrator.moveToApp({
            sysIds: [
                '34e04723799432108aa8fcb57505d952',
                'cb243962f1571100a92eb60da2bce522',
                '7d45011873670010e2fda4038bf6a79e',
            ],
        })

        //Temp files should have been deleted after download
        const volFiles = Object.keys(vol.toJSON())
        expect(volFiles.some((v) => v.startsWith(os.tmpdir()) && v.endsWith('.xml'))).toBeFalsy()

        const files = project.getFiles()
        expect(files.some((f) => f.getPath().endsWith('businessrule.now.ts'))).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('acl.now.ts'))).toBeTruthy()
        expect(files.some((f) => f.getPath().endsWith('dictionary.now.ts'))).toBeTruthy()

        expect(files.some((f) => f.getPath().endsWith('.claims.json'))).toBeTruthy()
        expect(result.changedFiles).toHaveLength(5)

        expect(telemetry.startTimerEvent).toHaveBeenCalledWith('move.to-app')
        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
    })
})
